import { QueryClient } from '@tanstack/react-query'

/**
 * Creates a new QueryClient with production-ready defaults.
 *
 * Used in QueryProvider to create per-request client on the server
 * and a singleton client on the browser.
 */
export function makeQueryClient(): QueryClient {
  return new QueryClient({
    defaultOptions: {
      queries: {
        // Data is considered fresh for 60 seconds by default
        staleTime: 60_000,
        // Retry once on failure (default 3 is too aggressive)
        retry: 1,
        // Don't refetch on window focus in dev (annoying)
        refetchOnWindowFocus: process.env.NODE_ENV === 'production',
      },
      mutations: {
        retry: 0,
      },
    },
  })
}

let browserQueryClient: QueryClient | undefined

/**
 * Returns the singleton QueryClient for browser usage.
 * Creates it on first call. Safe to call in Client Components.
 */
export function getQueryClient(): QueryClient {
  if (typeof window === 'undefined') {
    // Server: always make a new client (prevents cross-request state sharing)
    return makeQueryClient()
  }
  // Browser: reuse the same client across renders
  browserQueryClient ??= makeQueryClient()
  return browserQueryClient
}

'use client'

import { useMemo } from 'react'
import {
  Sidebar,
  SidebarContent,
  SidebarHeader,
} from '@/components/ui/sidebar'
import { SidebarNavGroup } from '@/components/app/sidebar/SidebarNavGroup'
import { SidebarUserFooter } from '@/components/app/sidebar/SidebarUserFooter'
import { APP_NAV, type NavRole } from '@/components/app/sidebar/nav-config'
import type { PlanTier } from '@/lib/billing/feature-gate'

interface AppSidebarProps {
  plan: PlanTier
  user: {
    name: string
    email: string
    avatarUrl?: string | null
  }
  studioName: string
  studioLogoUrl?: string | null
  role: NavRole
  locationCount: number
  /** Serialized from server — Set<string> → JSON array → passed as prop */
  permissionKeys?: string[]
}

export function AppSidebar({
  plan,
  user,
  studioName,
  studioLogoUrl,
  role,
  locationCount,
  permissionKeys = [],
}: AppSidebarProps) {
  const permissions = useMemo(() => new Set(permissionKeys), [permissionKeys])

  const navGroups = useMemo(() => {
    return APP_NAV
      .filter((group) => !(group.condition === 'multi-location' && locationCount <= 1))
      .map((group) => ({
        ...group,
        items: group.items.filter((item) => {
          if (!item.requiredRoles.includes(role)) return false
          if (item.requiredPermission && !permissions.has(item.requiredPermission)) return false
          return true
        }),
      }))

'use client'

import { createContext, useContext, useMemo } from 'react'

interface PermissionsContextValue {
  canDo: (key: string) => boolean
  permissions: ReadonlySet<string>
}

const PermissionsContext = createContext<PermissionsContextValue>({
  canDo: () => false,
  permissions: new Set(),
})

interface PermissionsProviderProps {
  /** Serialized as JSON array from the server component */
  permissionKeys: string[]
  children: React.ReactNode
}

export function PermissionsProvider({ permissionKeys, children }: PermissionsProviderProps) {
  const permissions = useMemo(() => new Set(permissionKeys), [permissionKeys])

  const value = useMemo<PermissionsContextValue>(
    () => ({
      canDo: (key: string) => permissions.has(key),
      permissions,
    }),
    [permissions],
  )

  return <PermissionsContext.Provider value={value}>{children}</PermissionsContext.Provider>
}

export function usePermissions() {
  return useContext(PermissionsContext)
}
